import chess

def material(board):
    vals = {chess.PAWN:100, chess.KNIGHT:320, chess.BISHOP:330, chess.ROOK:500, chess.QUEEN:900, chess.KING:0}
    score = 0
    for sq in chess.SQUARES:
        p = board.piece_at(sq)
        if p:
            v = vals[p.piece_type]
            if p.color == chess.WHITE:
                score += v
            else:
                score -= v
    return score

def minimax(board, depth, alpha, beta, maximizing):
    if board.is_checkmate():
        return -9999 if maximizing else 9999
    if board.is_stalemate() or board.is_insufficient_material():
        return 0
    if depth == 0:
        return material(board)
    if maximizing:
        best = -99999
        for move in board.legal_moves:
            board.push(move)
            val = minimax(board, depth-1, alpha, beta, False)
            board.pop()
            best = max(best, val)
            alpha = max(alpha, best)
            if beta <= alpha:
                break
        return best
    else:
        best = 99999
        for move in board.legal_moves:
            board.push(move)
            val = minimax(board, depth-1, alpha, beta, True)
            board.pop()
            best = min(best, val)
            beta = min(beta, best)
            if beta <= alpha:
                break
        return best

def best_moves(fen, name, depth=3):
    board = chess.Board(fen)
    results = []
    for move in board.legal_moves:
        san = board.san(move)
        board.push(move)
        score = minimax(board, depth-1, -99999, 99999, False)
        board.pop()
        results.append((score, san, move.uci()))
    results.sort(reverse=True)
    print(f"=== {name} === Top 10 moves (depth {depth}):")
    for score, san, uci in results[:10]:
        print(f"  {score:+6d}  {san:8s}  {uci}")
    print()

